"""FlyDSL batched bf16 GEMM out[i] = a[i] @ b[i] with b stored (k, n), for the fixed n = _N and k = _K.

Each (batch, column tile) workgroup DMAs all of K to LDS; C is stored from registers."""

import functools

import flydsl.compiler as flyc
import flydsl.expr as fx
import torch
from flydsl._mlir import ir
from flydsl._mlir.dialects import arith as arith_d
from flydsl._mlir.dialects import llvm
from flydsl._mlir.dialects import rocdl as rocdl_d
from flydsl._mlir.dialects import vector as vector_d
from flydsl.compiler import from_c_void_p
from flydsl.expr import arith, const_expr, range_constexpr, rocdl
from flydsl.expr.typing import T, Vector

_N = 512
_K = 128
_TILE_N = 64
_N_TILES = _N // _TILE_N
_WARP = 64
_WARPS = 4
_THREADS = _WARP * _WARPS
_DMA = 16
_B_ROW_BYTES = _TILE_N * 2  # 128
_A_ROW_BYTES = _K * 2  # 256
_B_LDS_BYTES = _K * _B_ROW_BYTES  # 16 KiB
_CUS = 256  # workgroups p, p + _CUS, ... share a CU
_XCDS = 8  # workgroup p runs on XCD p % _XCDS
_C_STORE_AUX = 17  # sc0 sc1
_DMA_BITS = "sc0"  # no nt: B stays in L2 across back-to-back calls
_A_FIRST_M = frozenset({8, 12, 16, 24, 32, 40, 48, 56, 60, 64})  # A DMA issued before B
_KSPLIT = {8: 4, 12: 4, 16: 4, 24: 2, 32: 2, 40: 2, 48: 2}  # DMA-wait chunks along k
_MFMA_SKEW_M = frozenset({40, 48})  # MFMAs one chunk behind the DMA wait
_REMAP_M = frozenset({12, 16, 32, 56, 60, 64, 112})  # a CU takes consecutive tiles
_ROW4_M = frozenset({112})  # every wave stores whole rows of every fourth row block
_MIXED_M = frozenset({80, 96})  # whole rows of block w, then halves of the rest
_MIX4_M = frozenset({60, 64})  # a whole-row and a half-row wave pair
_ROT_M = frozenset({8, 12, 40})  # the waves' row blocks move with the CU slot
_SLOT_DELAY_M = frozenset({8, 16, 80})  # later CU slots start their wait late
_A_TRIM_M = frozenset({40})  # A DMA moves only the m real rows


def _rsrc(ptr, byte_base, nbytes):
    addr = fx.Int64(fx.ptrtoint(ptr)) + byte_base
    base = llvm.IntToPtrOp(ir.Type.parse("!llvm.ptr"), fx.arith.unwrap(addr)).result
    return rocdl.MakeBufferRsrcOp(
        ir.Type.parse("!llvm.ptr<8>"),
        base,
        fx.arith.unwrap(arith.constant(0, type=T.i16)),
        fx.arith.unwrap(arith.constant(nbytes, type=T.i64)),
        fx.arith.unwrap(arith.constant((7 << 12) | (4 << 15), type=T.i32)),
    ).result


def _ptr(tensor):
    return from_c_void_p(fx.BFloat16, tensor.data_ptr(), assumed_align=16)


def _gep(base_ptr, byte_offset=None, static_byte_offset=0):
    base_ptr = fx.arith.unwrap(base_ptr)
    if byte_offset is None:
        dyn, raw = [], [int(static_byte_offset)]
    else:
        dyn, raw = [fx.arith.unwrap(byte_offset)], [-(2**31)]
    return llvm.GEPOp(base_ptr.type, base_ptr, dyn, raw, T.i8, None).result


def _b_swz(row):
    # XOR on 16-byte slot bits 1-2 only, so each 32-byte (16-column) block stays whole for the transposed read.
    return (((row >> 1) & 1) << 1) | (((row >> 3) & 1) << 2)


@functools.cache
def _launcher(batch, m, device):
    kernel = _build(batch, m)
    a_ex = torch.empty((batch, m, _K), device=device, dtype=torch.bfloat16)
    b_ex = torch.empty((batch, _K, _N), device=device, dtype=torch.bfloat16)
    c_ex = torch.empty((batch, m, _N), device=device, dtype=torch.bfloat16)
    # Preload the pointer arguments into SGPRs so the first DMA need not wait on kernarg loads.
    return flyc.compile[{"llvm_options": {"amdgpu-kernarg-preload-count": 6}}](
        kernel,
        _ptr(c_ex),
        _ptr(a_ex),
        _ptr(b_ex),
        fx.Stream(torch.cuda.current_stream(device)),
    )


def _build(batch, m):
    MB = (m + 15) // 16
    TILE_M = MB * 16
    A_LDS_OFF = _B_LDS_BYTES
    LDS_BYTES = _B_LDS_BYTES + TILE_M * _A_ROW_BYTES
    B_LOADS = _B_LDS_BYTES // (_THREADS * _DMA)  # 4
    A_DMA_TOTAL = (m if m in _A_TRIM_M else TILE_M) * _A_ROW_BYTES // _DMA  # vectors
    A_LOADS = (A_DMA_TOTAL + _THREADS - 1) // _THREADS
    A_PARTIAL = A_DMA_TOTAL % _THREADS != 0
    LdsArr = fx.Array[fx.BFloat16, LDS_BYTES // 2, 16]
    GRID = batch * _N_TILES
    A_FIRST = m in _A_FIRST_M
    N_RB = (MB + 1) // 2  # row blocks per wave
    STEPS = _K // 32
    KSPLIT = _KSPLIT.get(m, 1)
    REMAP = m in _REMAP_M and GRID % _CUS == 0
    SKEW = m in _MFMA_SKEW_M and KSPLIT > 1
    ROW4 = m in _ROW4_M
    MIXED = m in _MIXED_M
    MIX4 = m in _MIX4_M
    assert KSPLIT == 1 or (A_FIRST and not (ROW4 or MIXED or MIX4))
    assert not ROW4 or (MB > _WARPS and MB % _WARPS != 0)
    assert not MIXED or _WARPS < MB <= 2 * _WARPS
    assert not MIX4 or MB == _WARPS

    @flyc.kernel(known_block_size=[_THREADS, 1, 1])
    def bmm_nn_n512_k128(C: fx.Pointer, A: fx.Pointer, B: fx.Pointer):
        acc_init = arith.constant_vector(0.0, T.vec(4, T.f32))
        bf16x8_ty = fx.Vector.make_type(8, fx.BFloat16)
        v4bf16 = T.vec(4, T.bf16)
        pid = fx.block_idx.x
        pid_i = arith.index_cast(T.i32, fx.Index(pid))

        def i32(v):
            return arith.constant(v, type=T.i32)

        if const_expr(REMAP):
            # A CU's workgroups take consecutive tiles t of its XCD; bi % _XCDS stays the XCD, so a batch keeps its L2.
            q = arith_d.remui(pid_i, i32(_CUS))
            slot = arith_d.divui(pid_i, i32(_CUS))
            xcd = arith_d.remui(q, i32(_XCDS))
            cu = arith_d.divui(q, i32(_XCDS))
            t = arith_d.addi(arith_d.muli(cu, i32(GRID // _CUS)), slot)
            bi_i = arith_d.addi(xcd, arith_d.andi(t, i32(~(_N_TILES - 1))))
            nt_i = arith_d.andi(t, i32(_N_TILES - 1))
            bi = fx.Index(arith.index_cast(T.index, bi_i))
            nt = fx.Index(arith.index_cast(T.index, nt_i))
        else:
            bi = fx.Index(arith.index_cast(T.index, arith_d.remui(pid_i, i32(batch))))
            nt = fx.Index(arith.index_cast(T.index, arith_d.divui(pid_i, i32(batch))))
        bi64 = fx.Int64(bi)
        a_rsrc = _rsrc(A, bi64 * (m * _A_ROW_BYTES), m * _A_ROW_BYTES)
        b_rsrc = _rsrc(B, bi64 * (_K * _N * 2), _K * _N * 2)
        c_rsrc = _rsrc(C, bi64 * (m * _N * 2), m * _N * 2)

        lds_base = fx.SharedAllocator().allocate(LdsArr).peek().ptr
        lds_i64 = fx.Int64(fx.ptrtoint(lds_base))
        a_lds_ptr = lds_base + A_LDS_OFF // 2

        tid = fx.thread_idx.x
        wid = tid // _WARP
        lane = tid % _WARP
        g = lane // 16
        L = lane % 16

        warp_offset = rocdl.readfirstlane(
            T.i64,
            arith.index_cast(
                T.i64, fx.Index(wid) * arith.constant(_WARP * _DMA, index=True)
            ),
        )

        def dma(rsrc, lds_off, global_offset, bits):
            llvm.InlineAsmOp(
                None,
                [lds_off, global_offset, rsrc],
                "s_mov_b32 m0, $0\n\tbuffer_load_dwordx4 $1, $2, 0 offen "
                + bits
                + " lds",
                "s,v,s",
                has_side_effects=True,
            )

        def lds_ptr3(byte_i64):
            return llvm.IntToPtrOp(
                ir.Type.parse("!llvm.ptr<3>"), fx.arith.unwrap(byte_i64)
            ).result

        def issue_b():
            # B: LDS row r (k) holds the tile's 64 columns; physical 16 B slot p holds logical slot p ^ swz(r).
            b_lds = _gep(lds_ptr3(lds_i64), warp_offset)
            nt_bytes = nt * _B_ROW_BYTES
            for ii in range_constexpr(B_LOADS):
                gt = _THREADS * ii + tid
                row = gt // 8
                slot = (gt % 8) ^ _b_swz(row)
                goff = row * (_N * 2) + nt_bytes + slot * _DMA
                if const_expr(ii > 0):
                    b_lds = _gep(b_lds, static_byte_offset=_THREADS * _DMA)
                dma(b_rsrc, b_lds, arith.index_cast(T.i32, fx.Index(goff)), _DMA_BITS)

        def issue_a():
            # A: LDS row i holds 256 B; physical slot p holds logical slot p ^ (i & 15). Rows >= m read zero.
            a_lds = _gep(lds_ptr3(lds_i64 + fx.Int64(A_LDS_OFF)), warp_offset)
            for ii in range_constexpr(A_LOADS):
                gt = _THREADS * ii + tid
                row = gt // 16
                slot = (gt % 16) ^ (row % 16)
                goff = row * _A_ROW_BYTES + slot * _DMA
                if const_expr(ii > 0):
                    a_lds = _gep(a_lds, static_byte_offset=_THREADS * _DMA)
                if const_expr(A_PARTIAL and ii == A_LOADS - 1):
                    if gt < A_DMA_TOTAL:
                        dma(
                            a_rsrc,
                            a_lds,
                            arith.index_cast(T.i32, fx.Index(goff)),
                            _DMA_BITS,
                        )
                else:
                    dma(
                        a_rsrc,
                        a_lds,
                        arith.index_cast(T.i32, fx.Index(goff)),
                        _DMA_BITS,
                    )

        if const_expr(A_FIRST):
            issue_a()
            issue_b()
        else:
            issue_b()
            issue_a()
        if const_expr(m in _SLOT_DELAY_M):
            slot = fx.Index(pid) // _CUS
            for k in range_constexpr(1, GRID // _CUS):
                if slot >= k:
                    llvm.InlineAsmOp(None, [], "s_sleep 0", "", has_side_effects=True)

        def kwait(c):
            # With A issued first, each wave's B DMAs are its youngest VMEM ops and B DMA ii holds k-step ii, so
            # vmcnt(left) retires A and the B chunks up to c; the barrier makes every wave's share visible.
            left = B_LOADS - (c + 1) * (B_LOADS // KSPLIT)
            llvm.InlineAsmOp(
                None,
                [],
                f"s_waitcnt vmcnt({left})\n\ts_barrier",
                "",
                has_side_effects=True,
            )
            if const_expr(KSPLIT > 1):
                rocdl.sched_barrier(0)

        if const_expr(KSPLIT == 1):
            kwait(0)

        r_lane = 8 * g + L // 4

        # Raised until the stores, so on every SIMD the waves still computing win issue over those storing.
        llvm.InlineAsmOp(None, [], "s_setprio 2", "", has_side_effects=True)

        def b_frag(s, half, b, bcf=False):
            if const_expr(bcf):
                slot = (half * 4 + L % 4) ^ _b_swz(r_lane)
                off = r_lane * _B_ROW_BYTES + slot * 16 + 8 * (b ^ ((L // 2) % 2))
            else:
                colb = (half * 32 + (L % 4) * 8 + 4 * b) * 2
                slot = (colb // 16) ^ _b_swz(r_lane)
                off = r_lane * _B_ROW_BYTES + slot * 16 + colb % 16
            rd = _gep(lds_ptr3(lds_i64), fx.Int64(off))
            lo = rocdl.ds_read_tr16_b64(
                v4bf16, _gep(rd, static_byte_offset=(32 * s) * _B_ROW_BYTES)
            ).result
            hi = rocdl.ds_read_tr16_b64(
                v4bf16, _gep(rd, static_byte_offset=(32 * s + 4) * _B_ROW_BYTES)
            ).result
            lo = fx.Vector(lo, (4,), fx.BFloat16)
            hi = fx.Vector(hi, (4,), fx.BFloat16)
            return lo.shuffle(hi, [0, 1, 2, 3, 4, 5, 6, 7])

        def a_frag(row, phys):
            elem = fx.Int64(row * _K) + fx.Int64(phys * 8)
            return fx.ptr_load(a_lds_ptr + elem, result_type=bf16x8_ty)

        def a_frag_p(s, blk):
            phys = (4 * s + g) ^ L
            return a_frag(blk * 16 + L, phys)

        R = L // 2 + 8 * (L % 2)

        def a_frag_w(s, blk):
            row = blk * 16 + R
            return a_frag(row, (4 * s + g) ^ (row % 16))

        def mfma(b, a, acc):
            return rocdl.mfma_f32_16x16x32_bf16(T.vec(4, T.f32), [b, a, acc, 0, 0, 0])

        def pack(acc0, acc1):
            c0 = Vector(acc0).to(fx.BFloat16)
            c1 = Vector(acc1).to(fx.BFloat16)
            return c0.shuffle(c1, [0, 1, 2, 3, 4, 5, 6, 7])

        def store_c(v, off):
            rocdl_d.RawPtrBufferStoreOp(
                v,
                c_rsrc,
                fx.arith.unwrap(arith.index_cast(T.i32, fx.Index(off))),
                fx.arith.constant(0),
                aux=ir.IntegerAttr.get(T.i32, _C_STORE_AUX),
            )

        def unswap_bcf(vals):
            hi32 = fx.arith.unwrap(g >= 2)
            return [arith_d.select(hi32, vals[d ^ 2], vals[d]) for d in range(4)]

        def store_half(acc, blk, wc, bcf=False):
            v = pack(acc[0], acc[1])
            if const_expr(bcf):
                v = v.bitcast(fx.Int32)
                v = unswap_bcf([fx.arith.unwrap(v[d]) for d in range(4)])
                v = vector_d.from_elements(T.vec(4, T.i32), v)
            else:
                v = fx.arith.unwrap(v)
            store_c(v, (blk * 16 + L) * (_N * 2) + (nt * _TILE_N + wc * 32 + g * 8) * 2)

        # Lanes L and L ^ 1 (rows R) swap one piece by DPP, so each of the block's two stores writes whole rows.
        def store_lines(acc, blk, bcf):
            h = L % 2
            odd = fx.arith.unwrap(h == 1)
            p0 = pack(acc[0], acc[1]).bitcast(fx.Int32)
            p1 = pack(acc[2], acc[3]).bitcast(fx.Int32)
            own0 = [fx.arith.unwrap(p0[d]) for d in range(4)]
            own1 = [fx.arith.unwrap(p1[d]) for d in range(4)]
            send = [arith_d.select(odd, own0[d], own1[d]) for d in range(4)]
            recv = [
                rocdl_d.update_dpp(T.i32, sd, sd, 0xB1, 0xF, 0xF, True) for sd in send
            ]
            st0 = [arith_d.select(odd, recv[d], own0[d]) for d in range(4)]
            st1 = [arith_d.select(odd, own1[d], recv[d]) for d in range(4)]
            if const_expr(bcf):
                st0 = unswap_bcf(st0)
                st1 = unswap_bcf(st1)
            for half, vals in ((0, st0), (1, st1)):
                v = vector_d.from_elements(T.vec(4, T.i32), vals)
                off = (blk * 16 + 8 * half + L // 2) * (_N * 2) + (
                    nt * _TILE_N + g * 8 + h * 32
                ) * 2
                store_c(v, off)

        # Wave (wr, wc) owns column half wc of row blocks wr, wr + 2, ... Fragment reads go ahead of the MFMAs behind
        # a scheduling barrier (else LLVM waits on a read before nearly every MFMA), per DMA chunk when split.
        def paired(wr, wc, nrb=N_RB):
            bfp = []
            afp = []
            SPC = STEPS // KSPLIT
            accp = [[acc_init] * 2 for _ in range(nrb)]

            def mfmas(s0, s1):
                for s in range_constexpr(s0, s1):
                    for i in range_constexpr(nrb):
                        for b in range_constexpr(2):
                            accp[i][b] = mfma(bfp[s][b], afp[s][i], accp[i][b])

            for c in range_constexpr(KSPLIT):
                if const_expr(KSPLIT > 1):
                    kwait(c)
                if const_expr(KSPLIT == 1):
                    bfp = [
                        [b_frag(s, wc, b) for b in range_constexpr(2)]
                        for s in range_constexpr(STEPS)
                    ]
                    afp = [
                        [a_frag_p(s, 2 * i + wr) for i in range_constexpr(nrb)]
                        for s in range_constexpr(STEPS)
                    ]
                else:
                    for s in range_constexpr(c * SPC, (c + 1) * SPC):
                        bfp.append([b_frag(s, wc, b) for b in range_constexpr(2)])
                        afp.append(
                            [a_frag_p(s, 2 * i + wr) for i in range_constexpr(nrb)]
                        )
                rocdl.sched_barrier(0)
                if const_expr(SKEW and c > 0):
                    mfmas((c - 1) * SPC, c * SPC)
                    rocdl.sched_barrier(0)  # keeps them ahead of the next chunk's wait
            mfmas((KSPLIT - 1) * SPC if SKEW else 0, STEPS)
            llvm.InlineAsmOp(None, [], "s_setprio 0", "", has_side_effects=True)
            for i in range_constexpr(nrb):
                store_half(accp[i], 2 * i + wr, wc)

        # Wave w owns whole rows of blocks w, w + _WARPS, ...; each block's stores overlap the next block's MFMAs.
        def rows4(w, nrb, bcf=False):
            bfp = []
            afp = []
            for s in range_constexpr(STEPS):
                bfp.append(
                    [b_frag(s, bb // 2, bb % 2, bcf) for bb in range_constexpr(4)]
                )
                afp.append([a_frag_w(s, _WARPS * i + w) for i in range_constexpr(nrb)])
            rocdl.sched_barrier(0)
            accp = [[acc_init] * 4 for _ in range(nrb)]
            for i in range_constexpr(nrb):
                if const_expr(i > 0):
                    rocdl.sched_barrier(0)
                for s in range_constexpr(STEPS):
                    for b in range_constexpr(4):
                        accp[i][b] = mfma(bfp[s][b], afp[s][i], accp[i][b])
                if const_expr(i > 0):
                    rocdl.sched_barrier(0)
                store_lines(accp[i], _WARPS * i + w, bcf)

        # Wave w stores block w as rows4 does, then halves of the later blocks as paired does. With bcf, lanes with
        # L bit 1 read the other half of each B piece (no LDS bank conflicts), swapped back before the stores.
        def mixed(w):
            tails = [
                (_WARPS + j // 2, j % 2) for j in range(w, 2 * (MB - _WARPS), _WARPS)
            ]
            bfp = [
                [b_frag(s, bb // 2, bb % 2, True) for bb in range_constexpr(4)]
                for s in range_constexpr(STEPS)
            ]
            aff = [a_frag_w(s, w) for s in range_constexpr(STEPS)]
            aft = [
                [a_frag_p(s, blk) for (blk, _) in tails] for s in range_constexpr(STEPS)
            ]
            rocdl.sched_barrier(0)
            acc = [acc_init] * 4
            for s in range_constexpr(STEPS):
                for bb in range_constexpr(4):
                    acc[bb] = mfma(bfp[s][bb], aff[s], acc[bb])
            store_lines(acc, w, True)
            rocdl.sched_barrier(0)
            acct = [[acc_init] * 2 for _ in tails]
            for t, (_, wc) in enumerate(tails):
                for s in range_constexpr(STEPS):
                    for b in range_constexpr(2):
                        acct[t][b] = mfma(bfp[s][2 * wc + b], aft[s][t], acct[t][b])
            rocdl.sched_barrier(0)
            llvm.InlineAsmOp(None, [], "s_setprio 0", "", has_side_effects=True)
            for t, (blk, wc) in enumerate(tails):
                store_half(acct[t], blk, wc, bcf=True)

        wcr = wid
        if const_expr(m in _ROT_M):
            wcr = (wid + _WARPS - fx.Index(pid) // _CUS) % _WARPS
        if const_expr(MIXED):
            for w in range_constexpr(_WARPS):
                if wid == w:
                    mixed(w)
        elif const_expr(MIX4):
            if wid < 2:
                rows4(wid * 2, 1, bcf=True)
            else:
                paired(1, wid - 2)
        elif const_expr(ROW4):
            if wid < MB % _WARPS:
                rows4(wid, MB // _WARPS + 1)
            else:
                rows4(wid, MB // _WARPS)
        elif const_expr(MB == 1):
            if wcr < 2:
                paired(0, wcr)
            elif const_expr(KSPLIT > 1):
                # Idle waves still take part in every chunk barrier.
                for c in range_constexpr(KSPLIT):
                    kwait(c)
        elif const_expr(MB % 2 == 1):
            if wcr < 2:
                paired(0, wcr)
            else:
                paired(1, wcr - 2, N_RB - 1)
        else:
            paired(wid // 2, wid % 2)

    @flyc.jit
    def launch(C: fx.Pointer, A: fx.Pointer, B: fx.Pointer, stream: fx.Stream):
        bmm_nn_n512_k128(C, A, B).launch(
            grid=(GRID, 1, 1),
            block=(_THREADS, 1, 1),
            stream=stream,
            value_attrs={"rocdl.flat_work_group_size": f"{_THREADS},{_THREADS}"},
        )

    return launch


def run(*, a, b, trans_b, bias, out_dtype, out):
    if trans_b or bias is not None:
        raise ValueError("bmm_no_trans_b_n512_k128 expects trans_b=False and no bias")
    launch = _launcher(a.shape[0], a.shape[1], a.device)
    launch(_ptr(out), _ptr(a), _ptr(b), fx.Stream(torch.cuda.current_stream(a.device)))
